import sys

def can_empty(arr):
    """Check if all stones can be removed using the operation without swaps."""
    n = len(arr)
    if n == 0:
        return True

    # Process from left to right
    for i in range(n - 1):
        if arr[i] < 0:
            return False
        if i == n - 2:
            # Last pile can only be emptied by removing with its left neighbor
            if arr[i] != 0:
                return False
        else:
            arr[i + 1] -= arr[i]

    # Check if all are zero
    return all(x == 0 for x in arr)

def solve_test_case(s):
    """Solve a single test case."""
    import io

    # Parse input
    lines = s.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(lines[idx])
        idx += 1
        a = list(map(int, lines[idx].split()))
        idx += 1

        # Try without swap
        if can_empty(a):
            results.append("YES")
            continue

        # Try all possible swaps
        found = False
        for i in range(n - 1):
            # Create swapped version
            b = a.copy()
            b[i], b[i + 1] = b[i + 1], b[i]

            if can_empty(b):
                results.append("YES")
                found = True
                break

        if not found:
            results.append("NO")

    return '\n'.join(results)

