def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    adj = [[] for _ in range(n + 1)]
    for i in range(n - 1):
        u, v = map(int, lines[2 + i].split())
        adj[u].append(v)
        adj[v].append(u)

    # The key insight is that this problem can be solved using dynamic programming
    # on trees. We need to find optimal starting positions and paths.

    # For small cases, we can use a simple approach
    # For larger cases, we'll use tree DP

    def lca(u, v):
        """Find the lowest common ancestor"""
        depth = [-1] * (n + 1)
        parent = [0] * (n + 1)

        def dfs(node, p, d):
            depth[node] = d
            parent[node] = p
            for child in adj[node]:
                if child != p:
                    dfs(child, node, d + 1)

        dfs(1, 0, 0)

        # Binary lifting for LCA
        LOG = n.bit_length()
        up = [[0] * (LOG + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            up[i][0] = parent[i]
        for j in range(LOG):
            for i in range(1, n + 1):
                up[i][j] = up[up[i][j-1]][j-1]

        def get_kth_ancestor(node, k):
            for j in range(LOG + 1):
                if (k >> j) & 1:
                    node = up[node][j]
            return node

        if depth[u] < depth[v]:
            u, v = v, u
        u = get_kth_ancestor(u, depth[u] - depth[v])
        if u == v:
            return u
        for j in range(LOG, -1, -1):
            if up[u][j] != up[v][j]:
                u = up[u][j]
                v = up[v][j]
        return parent[u]

    def solve():
        # This is actually simpler: we need to find the maximum sum of selected vertices
        # The key is that Alice and Bob start at different vertices, then alternate moves

        # Based on the examples, the answer seems to be the sum of all chocolates
        # minus the ones that can't be reached due to path conflicts

        # Let's use a simpler approach: tree DP where we compute max path
        memo = {}

        def dp(node, cnt, depth):
            """Calculate max chocolates for subtree, cnt = number of remaining moves"""
            key = node
            if key in memo:
                return memo[key]

            max_val = 0
            for child in adj[node]:
                val = dp(child, cnt - 1, depth + 1)
                max_val = max(max_val, val)

            memo[node] = a[node - 1] + (max_val if cnt > 0 else 0)
            return memo[node]

        # For this problem, the optimal solution involves:
        # 1. Finding optimal starting positions
        # 2. Calculating total reachable chocolates

        # The pattern from examples suggests we need to consider all possible
        # pairings of starting vertices

        result = 0
        for start1 in range(1, n + 1):
            for start2 in range(1, n + 1):
                if start1 != start2:
                    # Calculate chocolates collectible from these starts
                    visited = {start1, start2}
                    total = a[start1 - 1] + a[start2 - 1]
                    # Continue collecting along paths
                    changed = True
                    while changed:
                        changed = False
                        for i in range(2, n):  # Alice and Bob alternate, limited by path length
                            # Check adjacent unvisited nodes
                            next_nodes = []
                            for node in list(visited):
                                for neighbor in adj[node]:
                                    if neighbor not in visited and neighbor != start1 and neighbor != start2:
                                        next_nodes.append(neighbor)
                            if next_nodes:
                                total += a[next_nodes[0] - 1]
                                visited.add(next_nodes[0])
                                changed = True
                    result = max(result, total)

        return result

    return solve()

