def is_geometric(a):
    n = len(a)
    if n <= 2:
        return True

    # If all elements are the same, it's a GP with ratio 1
    if all(x == a[0] for x in a):
        return True

    # Check if all elements are 0
    if all(x == 0 for x in a):
        return True

    # Special case: a[0] == 0 means all must be 0 (already handled above)
    # If a[0] is not 0, no element can be 0
    if a[0] == 0:
        return False

    # Calculate the ratio from first two non-zero elements
    # Find first pair where both are non-zero
    ratio = None
    for i in range(n - 1):
        if a[i] != 0 and a[i + 1] != 0:
            ratio = a[i + 1] / a[i]
            break

    # If no such pair exists (all zeros or all have zeros in sequence)
    if ratio is None:
        return False

    # Check all elements
    for i in range(n - 1):
        if a[i] == 0 or a[i + 1] == 0:
            return False
        if a[i + 1] != a[i] * ratio:
            return False

    return True


