def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse all events
    events = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        if parts[0] == '1':
            events.append((1, None))
        else:
            events.append((2, parts[1]))

    # Build intervals: between consecutive type-1 events, collect all friends who visit
    intervals = []  # each element is a set of friends in that interval
    current = set()
    for event in events:
        if event[0] == 1:
            intervals.append(current)
            current = set()
        else:
            current.add(event[1])
    intervals.append(current)  # add last interval

    # Get all unique friends
    friends = sorted(set(f for interval in intervals for f in interval))
    friend_to_idx = {f: i for i, f in enumerate(friends)}
    num_friends = len(friends)

    if num_friends == 0:
        return "0"

    # Build adjacency matrix: friends[i] and friends[j] have a conflict if they appear in the same interval
    adj = [[False] * num_friends for _ in range(num_friends)]
    for i in range(num_friends):
        for j in range(i + 1, num_friends):
            # Check if friend j appears in any interval where friend i appears
            for interval in intervals:
                if friend_to_idx[friends[i]] in friend_to_idx and friend_to_idx[friends[j]] in friend_to_idx:
                    # Better approach: check if both friends appear in same interval
                    if friends[i] in interval and friends[j] in interval:
                        adj[i][j] = adj[j][i] = True
                        break

    # Find maximum independent set using meet-in-the-middle
    mid = num_friends // 2

    # Left half: indices 0 to mid-1
    left_options = []

    def dfs_left(pos, mask, count):
        if pos == mid:
            left_options.append((mask, count))
            return
        # Option 1: Don't include friend at this position
        dfs_left(pos + 1, mask, count)
        # Option 2: Include friend at this position if no conflict with selected friends
        idx = pos
        conflict = False
        for already in range(pos):
            if adj[idx][already]:
                conflict = True
                break
        if not conflict:
            dfs_left(pos + 1, mask | (1 << idx), count + 1)

    dfs_left(0, 0, 0)

    # Right half: indices mid to num_friends-1
    right_options = []

    def dfs_right(pos, mask, count):
        if pos == num_friends:
            right_options.append((mask, count))
            return
        # Option 1: Don't include friend
        dfs_right(pos + 1, mask, count)
        # Option 2: Include friend if no conflict with selected friends
        actual_idx = pos
        conflict = False
        if pos > mid:
            for already in range(pos, num_friends):
                if adj[actual_idx][already]:
                    conflict = True
                    break
        else:  # pos == mid - but this case won't happen since pos starts at mid
            pass
        if not conflict:
            dfs_right(pos + 1, mask | (1 << actual_idx), count + 1)

    # Reimplement right half properly
    right_options = []

    def build_right(start, mask, count):
        if start == num_friends:
            right_options.append((mask, count))
            return
        # Option 1: Don't include friend at index 'start'
        build_right(start + 1, mask, count)
        # Option 2: Include friend at index 'start' if compatible
        conflict = False
        for already in range(start):
            if adj[start][already]:
                conflict = True
                break
        if not conflict:
            build_right(start + 1, mask | (1 << start), count + 1)

    build_right(0, 0, 0)

    # Find maximum combined set
    max_happy = 0
    for left_mask, left_count in left_options:
        for right_mask, right_count in right_options:
            if (left_mask & right_mask) == 0:
                max_happy = max(max_happy, left_count + right_count)

    return str(max_happy)


