    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])

    edges = []
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        edges.append((u, v))

    visit_parity = list(map(int, lines[m + 1].split()))

    # Build adjacency list
    adj = {i: [] for i in range(1, n + 1)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Find odd requirement vertices
    odd_req = [i + 1 for i, p in enumerate(visit_parity) if p == 1]

    # Handle edge cases
    if not odd_req:
        return "0\n"

    if len(odd_req) == 1:
        return "-1\n"

    # BFS to check connectivity and find paths
    def bfs(start, target):
        if start == target:
            return [start]
        visited = {start}
        queue = deque([start])
        path_result = []

        while queue:
            curr = queue.popleft()
            for neighbor in adj[curr]:
                if neighbor == target:
                    return path_result + [curr, neighbor]
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return None

    # Find all reachable from first odd vertex
    component = set()
    q = deque([odd_req[0]])
    component.add(odd_req[0])
    while q:
        node = q.popleft()
        for neighbor in adj[node]:
            if neighbor not in component:
                component.add(neighbor)
                q.append(neighbor)

    # Check all odd vertices in same component
    for v in odd_req:
        if v not in component:
            return "-1\n"

    # Build path
    path = []

    if len(odd_req) == 2:
        path = bfs(odd_req[0], odd_req[1])

        if path is None:
            if m == 0:
                return "-1\n"
            path = [odd_req[0], odd_req[1]]

        # Verify
        cnt = Counter(path)
        for i in range(n):
            if cnt[i + 1] % 2 != visit_parity[i]:
                return "-1\n"

        return f"{len(path)}\n{' '.join(map(str, path))} "

    else:  # More than 2 odd vertices
        # Find paths between pairs
        # Connect first two
        try:
            path = bfs(odd_req[0], odd_req[1])
        except:
            path = [odd_req[0]]

        if path is None:
            return "-1\n"

        # For remaining odd vertices (need even count for feasible solution)
        if len(odd_req) % 2 == 1:
            # Odd number of odd vertices - impossible
            return "-1\n"

        # Connect other pairs
        for i in range(2, len(odd_req), 2):
            try:
                path_pair = bfs(odd_req[i], odd_req[i + 1])
            except:
                path_pair = [odd_req[i]]

            if path_pair[0] == path_pair[-1] or len(path_pair) > 0:
                path.extend(path_pair)

        # Verify with correct number of paths
        cnt = Counter(path)
        for i in range(n):
            if cnt[i + 1] % 2 != visit_parity[i]:
                return "-1\n"

        return f"{len(path)}\n{' '.join(map(str, path))} "

MOD = 1000000007

def pow(n):
    return n * n

def mult_mod(a, b):
    return (a * b) % MOD

def mat_mul(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            for j in range(n):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def mat_pow(A, p):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = [row[:] for row in A]
    while p > 0:
        if p & 1:
            result = mat_mul(result, base)
        base = mat_mul(base, base)
        p >>= 1
    return result

