    n = int(lines[0])
    points = [list(map(int, line.split())) for line in lines[1:n+1]]

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_same_side(o, a, b, p1, p2):
        c1 = cross(o, a, p1)
        c2 = cross(o, a, p2)
        return (c1 > 0 and c2 > 0) or (c1 < 0 and c2 < 0) or (c1 == 0 and c2 == 0)

    def is_inside_triangle(p, a, b, c):
        c1 = cross(a, b, p)
        c2 = cross(b, c, p)
        c3 = cross(c, a, p)
        return (c1 > 0 and c2 > 0 and c3 > 0) or (c1 < 0 and c2 < 0 and c3 < 0)

    def segment_intersect(p1, p2, p3, p4):
        d1 = cross(p3, p4, p1)
        d2 = cross(p3, p4, p2)
        d3 = cross(p1, p2, p3)
        d4 = cross(p1, p2, p4)
        return ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0))

    def is_together(t1, t2):
        a, b, c = t1
        d, e, f = t2
        if is_inside_triangle(points[a], points[d], points[e], points[f]):
            return True
        if is_inside_triangle(points[d], points[a], points[b], points[c]):
            return True
        for u, v in [(a,b), (b,c), (c,a)]:
            for x, y in [(d,e), (e,f), (f,d)]:
                if segment_intersect(points[u], points[v], points[x], points[y]):
                    return True
        return False

    def is_disjoint(t1, t2):
        for p in t1:
            if is_inside_triangle(points[p], points[t2[0]], points[t2[1]], points[t2[2]]):
                return False
        for p in t2:
            if is_inside_triangle(points[p], points[t1[0]], points[t1[1]], points[t1[2]]):
                return False
        for u, v in [(t1[0],t1[1]), (t1[1],t1[2]), (t1[2],t1[0])]:
            for x, y in [(t2[0],t2[1]), (t2[1],t2[2]), (t2[2],t2[0])]:
                if segment_intersect(points[u], points[v], points[x], points[y]):
                    return False
        return True

    count = 0
    m = n
    for i in range(m - 2):
        for j in range(i + 1, m - 1):
            for k in range(j + 1, m):
                tri1 = (i, j, k)
                remaining = list(range(m))
