        theta = theta0 + omega * t
        return (R * math.cos(theta), R * math.sin(theta))

    def min_distance_to_origin(start, end):
        """Compute minimum distance from origin to line segment start->end"""
        ax, ay = start
        bx, by = end

        dx = bx - ax
        dy = by - ay

        if dx == 0 and dy == 0:
            return math.hypot(ax, ay)

        # Projection parameter t_param
        t_param = (ax * dx + ay * dy) / (dx * dx + dy * dy)

        if t_param < 0:
            return math.hypot(ax, ay)
        elif t_param > 1:
            return math.hypot(bx, by)
        else:
            proj_x = ax + t_param * dx
            proj_y = ay + t_param * dy
            return math.hypot(proj_x, proj_y)

    def can_reach_safe(t):
        """Check if Qwerty can reach Persephone at time t while maintaining safety distance r"""
        p = persephone_pos(t)

