            all_exit = min(all_exit, t_high)

        # y interval: mouse must satisfy y1 < riy + viy*t < y2
        if viy == 0:
            if not (y1 < riy < y2):
                return '-1'
        else:
            t_low = (y1 - riy) / viy
            t_high = (y2 - riy) / viy
            if viy < 0:
                t_low, t_high = t_high, t_low
            all_enter = max(all_enter, t_low)
            all_exit = min(all_exit, t_high)

    # We need t >= 0, t >= all_enter, t < all_exit
    valid_earliest = max(0.0, all_enter)

    if valid_earliest < all_exit:
        return str(valid_earliest)
    else:
        return '-1'


