        base_indices = [result[i] - 1 for i in range(N)]
        if len(set(base_indices)) != N:
            return False

        valid = True
        for i in range(N):
            for j in range(i + 1, N):
                if result[j] == -1 or result[i] == -1:
                    continue

                s1, b1 = spaceships[i], bases[result[i] - 1]
                s2, b2 = spaceships[j], bases[result[j] - 1]

                if segments_intersect(s1, b1, s2, b2):
                    valid = False
                    break
            if not valid:
                break
        return valid

    random.seed(0)

    for attempt in range(500):
        result = [0] * N
        used_bases = [False] * N

        for i in range(N):
            valid_match = False
            # Try bases in random order
            available = [j for j in range(N) if not used_bases[j]]
            random.shuffle(available)

            for base_idx in available:
                s = spaceships[i]
                b = bases[base_idx]

                is_valid = True
                for j in range(i):
                    if result[j] == -1:
                        continue
                    existing_s = spaceships[j]
                    existing_b = bases[result[j] - 1]

                    if segments_intersect(s, b, existing_s, existing_b):
                        is_valid = False
                        break

                if is_valid:
                    result[i] = base_idx + 1
                    used_bases[base_idx] = True
                    valid_match = True
                    break

            if not valid_match:
                result[i] = -1

        if all(r != -1 for r in result):
            return '\n'.join(map(str, result))

    # Fallback: deterministic approach with convex hull idea
    # Sort spaceships by x-coordinate and try pairing
    result = [0] * N
    for i in range(N):
        try:
            best = None
            for b_idx in range(N):
                s = spaceships[i]
                b = bases[b_idx]

                ok = True
                for j in range(i):
