    idx = 0
    t = int(lines[idx]) if idx < len(lines) else 0
    idx += 1
    results = []

    for _ in range(t):
        if idx >= len(lines):
            break
        parts = lines[idx].split()
        idx += 1
        n, m = int(parts[0]), int(parts[1])

        matrix = [list(lines[idx]) for idx in range(idx, idx + n)]
        idx += n

        count = 0

        # Axis-aligned squares
        # For size s, check all possible top-left positions
        for size in range(2, min(n, m) + 1):
            for r in range(n - size + 1):
                for c in range(m - size + 1):
                    # Check border is all 1s
                    valid = True

                    # Top and bottom borders
                    for j in range(c, c + size):
                        if matrix[r][j] != '1' or matrix[r + size - 1][j] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Left and right borders (excluding corners already checked)
                    for i in range(1, size - 1):
                        if matrix[r + i][c] != '1' or matrix[r + i][c + size - 1] != '1':
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check no 1s touching outside border
                    def check_isolation():
                        # Check 2-cell padding outside the square
                        for dr in range(-1, 2):
                            for dc in range(-1, 2):
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < n - size + 1 and 0 <= nc < m - size + 1:
                                    if not (0 <= nr < n and 0 <= nc < m):
                                        return False
                                    if (dr == 0 and dc == 0):
                                        continue
                                    if matrix[nr][nc] == '1':
                                        return False
                        return True

                    if check_isolation():
                        count += 1

        # Diagonal (diamond) squares
        # For size s (representing the "radius" from center), check all possible centers
        # Size 2 = minimum meaningful diamond
        for center_r in range(1, n - 1):
            for center_c in range(1, m - 1):
                for h in range(2, min(center_r, n - center_r - 1)):
                    if h + 1 >= m - center_c or h + 1 >= center_c + 1:
                        continue

                    # For diamond of "height" h+1 around center
                    # Border cells: |r - center_r| + |c - center_c| = h
                    valid = True

                    # Check all border cells are 1
                    prev = -1
                    for dr in range(-h, h + 1):
                        abs_dr = abs(dr)
                        max_dc = h - abs_dr
                        for dc in range(-max_dc, max_dc + 1):
                            dr, dc = dr, dc
                            if prev == dr + abs_dr:
                                pass

                            Mr, Mc = center_r + dr, center_c + dc
                            if not (0 <= Mr < n and 0 <= Mc < m):
                                valid = False
                                break
                            if matrix[Mr][Mc] != '1':
                                valid = False
                                break
                        if not valid:
                            break
                    if not valid:
                        continue

                    # Check no 1s touching outside
                    def diag_isolation():
                        # Check h+1 padding around
                        for off in range(h + 1):
                            for dr in range(-off, off + 1):
                                if abs(dr) <= off:
                                    for dc in range(-off, off + 1):
                                        if abs(dc) <= off:
                                            Mr, Mc = center_r + dr, center_c + dc
                                            if not (0 <= Mr < n and 0 <= Mc < m):
                                                return False
                                            if dr + dc == 0 and abs(dr) + abs(dc) <= h:
                                                continue
                                            if matrix[Mr][Mc] == '1':
                                                return False
                        return True

                    if diag_isolation():
                        count += 1

        results.append(str(count))

    return '\n'.join(results)

