def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    centers = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        centers.append((float(x), float(y)))

    # If less than 3 circles, can't form holes
    if n < 3:
        return "-1\n"

    # Check if all centers are collinear
    if n >= 3:
        x0, y0 = centers[0]
        for i in range(1, n):
            for j in range(i+1, n):
                x1, y1 = centers[i]
                x2, y2 = centers[j]
                # Cross product check for collinearity
                if abs((x1-x0)*(y2-y0) - (x2-x0)*(y1-y0)) < 1e-9:
                    # All three collinear
                    all_collinear = True
                    for k in range(3):
                        xk, yk = centers[k]
                        if abs((x1-x0)*(yk-y0) - (xk-x0)*(y1-y0)) > 1e-9:
                            all_collinear = False
                            break
                    if all_collinear:
                        # Check if remaining points are also collinear
                        remaining_collinear = True
                        for k in range(3, n):
                            for m in range(4, n):
                                if abs((x1-x0)*(centers[m][1]-y0) - (centers[m][0]-x0)*(y1-y0)) > 1e-9:
                                    remaining_collinear = False
                                    break
                            if not remaining_collinear:
                                break
                    if all_collinear:
                        pass  # Will be handled by computation anyway

    # Compute pairwise distances
    dists = []
    for i in range(n):
        for j in range(i+1, n):
            d = math.sqrt((centers[i][0]-centers[j][0])**2 + (centers[i][1]-centers[j][1])**2)
            dists.append((min(i,j), max(i,j), d))

    # For each triangle of 3 circles, check if it can form a hole
    # The maximum radius needed to cover the circumcircle hole
    results = []
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                cx1, cy1 = centers[i]
                cx2, cy2 = centers[j]
                cx3, cy3 = centers[k]

                # Compute circumcenter
                D = 2 * (cx1*(cy2-cy3) + cx2*(cy3-cy1) + cx3*(cy1-cy2))
                if abs(D) > 1e-9:
                    Ux = ((cx1**2 + cy1**2)*(cy2-cy3) + (cx2**2 + cy2**2)*(cy3-cy1) + (cx3**2 + cy3**2)*(cy1-cy2)) / D
                    Uy = ((cx1**2 + cy1**2)*(cx3-cx2) + (cx2**2 + cy2**2)*(cx1-cx3) + (cx3**2 + cy3**2)*(cx2-cx1)) / D

                    # Distance from circumcenter to each center
                    r1 = math.sqrt((cx1-Ux)**2 + (cy1-Uy)**2)
                    r2 = math.sqrt((cx2-Ux)**2 + (cy2-Uy)**2)
                    r3 = math.sqrt((cx3-Ux)**2 + (cy3-Uy)**2)

                    # Maximum distance
                    max_r = max(r1, r2, r3)
                    results.append(max_r)

    if results:
        result = max(results)
        if result == 0 or result < 1e-9:
            return "-1\n"
        return f"{result:.6f}\n"
