def count_prime_factor(n):
    count = 0
    d = 2
    while d * d <= n:
        while n % d == 0:
            count += 1
            n //= d
        d += 1
    if n > 1:
        count += 1
    return count

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True

def solution(input_str):
    data = input_str.strip().split('\n')
    n = int(data[0])
    a = list(map(int, data[1].split()))

    # For each number, compute prime factor count
    prime_counts = [count_prime_factor(num) for num in a]

    # dp[mask] = minimum vertices for subset mask
    memo = {}

    def dp(mask):
        if mask == 0:
            return 0

        if mask in memo:
            return memo[mask]

        # Count total prime factors in this subset
        total_factors = 0
        for i in range(n):
            if mask & (1 << i):
                total_factors += prime_counts[i]

        # For a single element
        if mask == 1:
            # Just one number
            if is_prime(a[0]):
                return 1
            else:
                # Composite: 1 internal (the number itself) + prime_factors leaves
                return 1 + prime_counts[0]

        # General case: try all possible splits
        # A split of mask into i (submask) and j = mask ^ i
        # dp[mask] = dp[i] + dp[j] + 1

        result = float('inf')
        for i in range(1, mask):
            if (i & mask) == i:  # i is submask
                j = mask ^ i
                if i == 0 or j == 0:
                    continue
                res = dp(i) + dp(j) + 1
                result = min(result, res)

        memo[mask] = result
        return result

    full_mask = (1 << n) - 1
    result = dp(full_mask)
    return str(result) + '\n'

import math

def solution(input_str):
    x, y = map(int, input_str.strip().split())

    if x == 1:
        return str(y)

    ans = 0

    while y > 0:
        g = math.gcd(x, y)

        if y % g == 0:
            # Can finish in one go
            ans += y // g
            y = 0
        else:
            # Move to the largest multiple of g less than y
            # Number of steps = 1 (go from y to y - remainder)
            remainder = y % g
            ans += 1
            y -= remainder

    return str(ans)

