def solution(mask):
    n = len(mask)

    # If all cells are empty in mask, output empty profile
    if '#' not in mask:
        return "\n0\n\n"

    # Parse '#' sequences from mask
    groups = []
    i = 0
    while i < n:
        if mask[i] == '#':
            start = i
            while i < n and mask[i] == '#':
                i += 1
            groups.append((start, i - start))
        else:
            i += 1

    if not groups:
        return "\n0\n\n"

    # Try different profile constructions
    # A simple approach: treat each group followed by possibly extended blocks

    for k in range(1, len(groups) + 1):
        # Try profile with sum of group lengths
        base_p = [g[1] for g in groups]

        for total_ext in range(0, 100):  # Try extending some blocks
            # Try small extensions
            new_p = base_p[:]
            for j in range(k):
                if len(base_p) > j and j < k - 1:
                    # Try adding extensions
                    for ext in range(1, 10):
                        new_p[j] += ext
                        if check_profile(n, mask, new_p):
                            print(len(new_p))
                            print(*(new_p))
                            return
            if check_profile(n, mask, new_p):
                print(len(new_p))
                print(*(new_p))
                return

    return "\n-1\n"

def check_profile(n, mask, p):
    """Check if profile p produces the given mask"""
    total_needed = sum(p) + len(p) - 1 if len(p) > 0 else 0

    if total_needed > n:
        return False

    if len(p) == 0:
        return all(c == '_' for c in mask)

    mask_computed = ['.'] * n

    # Compute all valid placements
    starts = [0] * (len(p) + 1)
    for i in range(len(p) - 1):
        starts[i+1] = starts[i] + p[i] + 1
    starts[-1] = starts[-2] + p[-1]
    max_start = n - starts[-1]

    # For each position in grid, check if covered in ALL valid placements
    for pos in range(n):
        always_covered = True
        for offset in range(max_start + 1):
            coverage = False
            for i in range(len(p)):
                if starts[i] + offset + starts[i+1] - starts[i] - 1 >= pos:
                    coverage = True
                    break
            if not coverage:
                always_covered = False
                break

        if always_covered:
            mask_computed[pos] = '#'
            if mask[pos] != '#':
                return False
        else:
            if mask[pos] == '#':
                return False

    return True

