        parent = [0] * (n + 1)
        dist[start] = 0
        queue = deque([start])

        while queue:
            curr = queue.popleft()
            for neighbor in adj[curr]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[curr] + 1
                    parent[neighbor] = curr
                    queue.append(neighbor)

        return dist, parent

    def get_path(start, end):
        dist, parent = bfs_distances(start)
        path = []
        curr = end
        while curr != start and curr != 0:
            path.append(curr)
            curr = parent[curr]
        if curr == start:
            path.append(start)
            return path[::-1]
        return []

