def solution(input_str):
    """
    Counts the number of different decompositions of n into Fibonacci numbers.
    F1 = 1, F2 = 2, Fi = Fi-1 + Fi-2 for i > 2
    """
    import sys
    from functools import lru_cache

    # Parse input
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    queries = [int(line) for line in lines[1:]]

    # Generate Fibonacci numbers up to 10^18
    fib = []
    a, b = 1, 2
    while a <= 10**18:
        fib.append(a)
        a, b = b, a + b

    n_fib = len(fib)

    def count_decompositions(n):
        """
        Memoization-based approach to count Fibonacci decompositions.
        Key insight: for any number n, if we find the largest Fibonacci number F_i <= n,
        we either include it or we don't.
        """
        @lru_cache(maxsize=None)
        def dp(n, max_idx):
            if n == 0:
                return 1
            if max_idx < 0 or fib[max_idx] > n:
                return 0

            # If fib[max_idx] cannot be used, move to next smaller
            if fib[max_idx] > n:
                return dp(n, max_idx - 1)

            # Option 1: Don't include fib[max_idx]
            # Option 2: Include fib[max_idx]
            return dp(n, max_idx - 1) + dp(n - fib[max_idx], max_idx - 1)

        return dp(n, n_fib - 1)

    results = []
    for n in queries:
        result = count_decompositions(n)
        results.append(str(result))

    return '\n'.join(results)

def solution(input_data):
    from collections import deque

    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    frog_data = {}
    pos_to_frog = {}

    for i in range(1, n + 1):
        parts = lines[i].split()
        p, a = int(parts[0]), int(parts[1])
        frog_data[i] = [p, a, True]
        pos_to_frog[p] = i

    remaining = set(range(1, n + 1))
    active_queue = deque(range(1, n + 1))

    while active_queue:
        frog_id = active_queue.popleft()
        if frog_id not in remaining:
            continue

        pos, a = frog_data[frog_id][0], frog_data[frog_id][1]

        if a <= 0:
            remaining.discard(frog_id)
            continue

        dest = (pos + a - 1) % m + 1

        if dest >= pos:
            cells = list(range(pos + 1, dest + 1))
        else:
            cells = list(range(pos + 1, m + 1)) + list(range(1, dest + 1))

        killed = []
        for cell in cells:
            if cell in pos_to_frog:
                pid = pos_to_frog[cell]
                if pid in remaining and pid != frog_id:
                    killed.append(pid)
                    del pos_to_frog[cell]

        for pid in killed:
            remaining.discard(pid)
            frog_data[pid][1] = 0

        frog_data[frog_id][1] -= len(killed)

        if frog_data[frog_id][1] > 0:
            active_queue.append(frog_id)

    result = sorted(remaining)
    result_str = str(len(result)) + '\n' + ' '.join(map(str, result))
    return result_str

