def solution(s):
    import sys

    n = int(s.strip())
    coins = [1, 5, 10, 50]

    if n == 1:
        return "4"
    if n == 2:
        return "10"

    # Use a set to track reachable sums
    # Start with sum 0
    reachable = {0}

    for _ in range(n):
        new_reachable = set()
        for s in reachable:
            for coin in coins:
                new_reachable.add(s + coin)
        reachable = new_reachable

    return str(len(reachable))

def solution(input_str):
    n, k = list(map(int, input_str.strip().split()))

    reps = set()

    def invert(s):
        return ''.join('1' if c == '0' else '0' for c in s)

    def reverse(s):
        return s[::-1]

    for i in range(1 << n):
        s = format(i, f'0{n}b')
        variants = {
            s,
            reverse(s),
            invert(s),
            reverse(invert(s))
        }
        reps.update(variants)

    sorted_reps = sorted(list(reps))

    if k > len(sorted_reps):
        return "-1"

    return sorted_reps[k-1]
